/* =========================================================
   GalaxyMag
   Sync Desktop Menu With Mobile Side Slider
   تحت الضوء
   ========================================================= */

(function () {

    function buildMobileMenu() {

        var desktopMenu =
            document.querySelector('#galaxymag-main-menu-nav');

        var mobileMenu =
            document.querySelector('#slide-menu .mobile-menu');


        /* -----------------------------------------------------
           التأكد من وجود القائمتين
           ----------------------------------------------------- */

        if (!desktopMenu || !mobileMenu) {
            return;
        }


        /* -----------------------------------------------------
           نسخ القائمة الرئيسية
           ----------------------------------------------------- */

        var newMenu =
            desktopMenu.cloneNode(true);


        /* منع تكرار ID الخاص بالقائمة */
        newMenu.removeAttribute('id');


        /* -----------------------------------------------------
           إزالة عناصر الـMega Menu الخاصة بالديسكتوب
           ----------------------------------------------------- */

        newMenu.querySelectorAll('.getMega').forEach(function (el) {
            el.remove();
        });


        newMenu.querySelectorAll('.mega-menu').forEach(function (el) {

            if (el.parentElement) {
                el.parentElement.removeChild(el);
            }

        });


        /* -----------------------------------------------------
           تنظيف Mobile Menu القديم
           ----------------------------------------------------- */

        mobileMenu.innerHTML = '';


        /* -----------------------------------------------------
           إضافة القائمة الجديدة
           ----------------------------------------------------- */

        mobileMenu.appendChild(newMenu);


        /* =====================================================
           تجهيز القوائم الفرعية
           ===================================================== */

        var items =
            newMenu.querySelectorAll('li');


        items.forEach(function (li) {

            /*
             * البحث عن UL مباشر داخل العنصر
             */
            var submenu =
                li.querySelector(':scope > ul');


            /*
             * لو مفيش قائمة فرعية نكمل
             */
            if (!submenu) {
                return;
            }


            /* تعريف العنصر كـDropdown */
            li.classList.add('has-sub');


            /* إخفاء القائمة الفرعية */
            submenu.classList.add('m-sub');

            submenu.style.display =
                'none';


            /* منع إنشاء أكثر من سهم */
            if (
                li.querySelector(
                    ':scope > .submenu-toggle'
                )
            ) {
                return;
            }


            /* -------------------------------------------------
               إنشاء سهم Dropdown
               ------------------------------------------------- */

            var toggle =
                document.createElement('span');


            toggle.className =
                'submenu-toggle';


            /* -------------------------------------------------
               الضغط على السهم
               ------------------------------------------------- */

            toggle.addEventListener(
                'click',
                function (event) {

                    event.preventDefault();
                    event.stopPropagation();


                    var isOpen =
                        li.classList.contains('show');


                    /* إغلاق القوائم الأخرى */
                    newMenu
                        .querySelectorAll(
                            'li.has-sub.show'
                        )
                        .forEach(function (otherLi) {

                            if (otherLi !== li) {

                                otherLi.classList.remove(
                                    'show'
                                );


                                var otherSub =
                                    otherLi.querySelector(
                                        ':scope > ul'
                                    );


                                if (otherSub) {

                                    otherSub.style.display =
                                        'none';

                                }

                            }

                        });


                    /* -------------------------------------------------
                       فتح القائمة
                       ------------------------------------------------- */

                    if (!isOpen) {

                        li.classList.add(
                            'show'
                        );


                        submenu.style.display =
                            'block';

                    }


                    /* -------------------------------------------------
                       إغلاق القائمة
                       ------------------------------------------------- */

                    else {

                        li.classList.remove(
                            'show'
                        );


                        submenu.style.display =
                            'none';

                    }

                }
            );


            /* إضافة السهم */
            li.appendChild(toggle);

        });


        /* =====================================================
           الضغط على اسم الـDropdown نفسه
           ===================================================== */

        newMenu
            .querySelectorAll(
                'li.has-sub > a'
            )
            .forEach(function (link) {

                link.addEventListener(
                    'click',
                    function (event) {

                        /*
                         * مهم جدًا:
                         * نمنع الرابط من الذهاب للرئيسية
                         * حتى لو كان href="/" أو "#"
                         */

                        event.preventDefault();
                        event.stopPropagation();


                        var parent =
                            link.parentElement;


                        var submenu =
                            parent.querySelector(
                                ':scope > ul'
                            );


                        if (!submenu) {
                            return;
                        }


                        var isOpen =
                            parent.classList.contains(
                                'show'
                            );


                        /* -------------------------------------------------
                           إغلاق أي Dropdown آخر
                           ------------------------------------------------- */

                        newMenu
                            .querySelectorAll(
                                'li.has-sub.show'
                            )
                            .forEach(function (otherLi) {

                                if (otherLi !== parent) {

                                    otherLi.classList.remove(
                                        'show'
                                    );


                                    var otherSub =
                                        otherLi.querySelector(
                                            ':scope > ul'
                                        );


                                    if (otherSub) {

                                        otherSub.style.display =
                                            'none';

                                    }

                                }

                            });


                        /* -------------------------------------------------
                           فتح
                           ------------------------------------------------- */

                        if (!isOpen) {

                            parent.classList.add(
                                'show'
                            );


                            submenu.style.display =
                                'block';

                        }


                        /* -------------------------------------------------
                           إغلاق
                           ------------------------------------------------- */

                        else {

                            parent.classList.remove(
                                'show'
                            );


                            submenu.style.display =
                                'none';

                        }

                    }
                );

            });


        /* =====================================================
           اتجاه القائمة العربية
           ===================================================== */

        mobileMenu.setAttribute(
            'dir',
            'rtl'
        );


        console.log(
            'GalaxyMag Mobile Menu synchronized successfully.'
        );

    }


    /* =========================================================
       تشغيل القائمة
       ========================================================= */

    function startMenuFix() {

        /*
         * GalaxyMag يحتاج وقت لإنشاء Side Menu
         */

        setTimeout(
            buildMobileMenu,
            700
        );


        /*
         * محاولة احتياطية
         */

        setTimeout(
            buildMobileMenu,
            1800
        );

    }


    /* =========================================================
       بدء التنفيذ
       ========================================================= */

    if (
        document.readyState === 'loading'
    ) {

        document.addEventListener(
            'DOMContentLoaded',
            startMenuFix
        );

    } else {

        startMenuFix();

    }

})();
